var targetGroup = new api.THREE.Group();
                var ringColors = [0xE8593C, 0xF2A65A, 0xF5F0E8];
                for (var i = 0; i < 3; i++) {
                  var ring = new api.THREE.Mesh(
                    new api.THREE.RingGeometry(0.6 - i * 0.2, 0.8 - i * 0.2, 32),
                    new api.THREE.MeshBasicMaterial({ color: ringColors[i], side: api.THREE.DoubleSide })
                  );
                  targetGroup.add(ring);
                }
                api.group.add(targetGroup);
                var dartGeometry = new api.THREE.SphereGeometry(0.08, 16, 16);
                var dartMaterial = new api.THREE.MeshPhongMaterial({ color: 0x2E86AB });
                var dart = new api.THREE.Mesh(dartGeometry, dartMaterial);
                dart.position.set(0.05, 0.05, 0.05);
                api.group.add(dart);
                return {
                  update: function(t) {
                    targetGroup.rotation.z = t * 0.01;
                    dart.position.z = 0.1 + Math.sin(t * 0.03) * 0.02;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W / 2, cy = H / 2;
                    var rings = [90, 60, 30];
                    var colors = ['#E8593C', '#F2A65A', '#2E86AB'];
                    for (var i = 0; i < rings.length; i++) {
                      ctx.beginPath();
                      ctx.arc(cx, cy, rings[i], 0, Math.PI * 2);
                      ctx.strokeStyle = colors[i];
                      ctx.lineWidth = 3;
                      ctx.stroke();
                    }
                    var seed = Math.floor(t / 40);
                    for (var d = 0; d < 5; d++) {
                      var angle = (seed + d) * 2.4;
                      var radius = 8 + ((seed * 7 + d * 13) % 15);
                      var dx = cx + Math.cos(angle) * radius;
                      var dy = cy + Math.sin(angle) * radius;
                      ctx.fillStyle = '#2E86AB';
                      ctx.beginPath();
                      ctx.arc(dx, dy, 5, 0, Math.PI * 2);
                      ctx.fill();
                    }
                  }
                };

return {
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W / 2, cy = H / 2;
                    var rings = [110, 75, 40];
                    var colors = ['#E8593C', '#F2A65A', '#2E86AB'];
                    for (var i = 0; i < rings.length; i++) {
                      ctx.beginPath();
                      ctx.arc(cx, cy, rings[i], 0, Math.PI * 2);
                      ctx.strokeStyle = colors[i];
                      ctx.lineWidth = 3;
                      ctx.stroke();
                    }
                    var offset = controls.offset !== undefined ? controls.offset : 20;
                    var count = controls.throws !== undefined ? controls.throws : 6;
                    for (var d = 0; d < count; d++) {
                      var angle = d * 2.4 + d * d * 0.3;
                      var radius = offset + (d % 3) * 6;
                      var dx = cx + Math.cos(angle) * radius;
                      var dy = cy + Math.sin(angle) * radius;
                      ctx.fillStyle = '#111827';
                      ctx.beginPath();
                      ctx.arc(dx, dy, 5, 0, Math.PI * 2);
                      ctx.fill();
                    }
                  }
                };
